import os,gzip,re,collections
def load(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    enc='utf-8'
    if b[:3]==b'\xef\xbb\xbf': b=b[3:]
    elif b[:2]==b'\xff\xfe': enc='utf-16-le'; b=b[2:]
    elif b[:2]==b'\xfe\xff': enc='utf-16-be'; b=b[2:]
    else:
        m=re.search(rb'#\s*charset:\s*(\S+)',b[:500])
        if m: enc=m.group(1).decode()
    return b.decode(enc)
c=collections.Counter()
for f in sorted(os.listdir('.')):
    t=load(f)
    d=f.split('-')[0]
